/**  Commandlar xatosi. `code` frontendda tarjima kalitiga aylanadi; PIN yoki kalit qiymati yo'q. */
export type ApiError = 
/**  PIN 6 ta raqamdan iborat emas. */
{ code: "INVALID_PIN" } | 
/**  PIN noto'g'ri. */
{ code: "WRONG_PIN" } | 
/**  Juda ko'p noto'g'ri urinish: kutish davom etmoqda. */
{ code: "LOCKED_OUT"; 
/**
 *  Qolgan kutish vaqti (soniyalarda). `u32`: TypeScript'da `bigint` bo'lmasligi uchun
 *  (kutish eng ko'pi bilan bir soat, sig'adi).
 */
retryAfterSeconds: number } | 
/**  PIN allaqachon o'rnatilgan. */
{ code: "ALREADY_SET_UP" } | 
/**  PIN hali o'rnatilmagan. */
{ code: "NOT_SET_UP" } | 
/**  Qurilma kaliti OS keyring'ida yo'q yoki bu bazaga mos emas. */
{ code: "KEY_UNAVAILABLE" } | 
/**  Baza qulflangan: avval PIN bilan ochish kerak. */
{ code: "LOCKED" } | 
/**  `.baraka` fayli paroli noto'g'ri. */
{ code: "WRONG_PASSWORD" } | 
/**  `.baraka` fayli buzilgan yoki noto'g'ri formatda. */
{ code: "CORRUPT_CONTAINER" } | 
/**  Parol juda qisqa. */
{ code: "WEAK_PASSWORD" } | 
/**  Ma'lumotlar bazasi bor, lekin kalit fayli yo'q (sozlab bo'lmaydi). */
{ code: "DATABASE_WITHOUT_KEY" } | 
/**  Biznes qoidasi buzildi. `rule` — domen xato kodi (masalan, `INSUFFICIENT_BALANCE`). */
{ code: "RULE"; 
/**  Domen xato kodi. */
rule: string } | 
/**  Kutilmagan ichki xato (batafsil log'da, foydalanuvchiga umumiy xabar). */
{ code: "INTERNAL" };

